#!/bin/bash
# Builds the caddy package into out/: the binary from main.go and go.mod with the flags of
# Caddy's own release build (.goreleaser.yml v2.11.7, lines 33-89), man pages and bash
# completion generated by that binary as Caddy does it (lines 26-31), and Caddy's
# packaging files from caddyserver/dist at DIST_REF. Then the same binary for Windows as a
# zip, with Caddy's icon and a version resource (see below). Fails unless every plugin of
# main.go is in both binaries. Needs go, git, gzip, zip, curl and nfpm on PATH; runs on
# linux/amd64.
#
# Environment: DIST_REF (commit of caddyserver/dist, required), XCADDY_REF (commit of
# caddyserver/xcaddy, for Caddy's icon, required), CADDY_ICO_SHA256 (its SHA-256, required),
# GOVERSIONINFO_VERSION (version of github.com/josephspurrier/goversioninfo, required),
# PKG_RELEASE (package revision, default 0).
set -euo pipefail

cd "$(dirname "$0")/.."
. scripts/plugins.sh

: "${DIST_REF:?set DIST_REF to a commit of caddyserver/dist}"
: "${XCADDY_REF:?set XCADDY_REF to a commit of caddyserver/xcaddy}"
: "${CADDY_ICO_SHA256:?set CADDY_ICO_SHA256 to the SHA-256 of xcaddy caddy.ico}"
: "${GOVERSIONINFO_VERSION:?set GOVERSIONINFO_VERSION to a version of goversioninfo}"
PKG_RELEASE="${PKG_RELEASE:-0}"

syso=resource_windows_amd64.syso
rm -rf build out "$syso"
trap 'rm -f "$syso"' EXIT
mkdir -p build/man build/windows out

CADDY_VERSION="$(go list -m -f '{{.Version}}' github.com/caddyserver/caddy/v2)"
CADDY_VERSION="${CADDY_VERSION#v}"
# one process instead of "sed | head": under pipefail, head closing the pipe early can make
# sed die of SIGPIPE and the whole assignment fail
PACKAGING_VERSION="$(awk -F'[][]' '/^## \[[0-9]/ { print $2; exit }' CHANGELOG.md)"
PLUGINS="$(plugin_imports main.go | paste -sd ' ' -)"
export CADDY_VERSION PKG_RELEASE PACKAGING_VERSION PLUGINS

echo "== caddy $CADDY_VERSION, package revision $PKG_RELEASE, packaging $PACKAGING_VERSION"
echo "== plugins: $PLUGINS"

CGO_ENABLED=0 GOOS=linux GOARCH=amd64 go build \
    -trimpath -mod=readonly -ldflags '-s -w' -tags nobadger,nomysql,nopgx \
    -o build/caddy .

build/caddy version
check_plugins build/caddy main.go

build/caddy manpage --directory build/man
gzip -9n build/man/*
build/caddy completion bash > build/bash-completion

git clone --quiet https://github.com/caddyserver/dist build/dist
git -C build/dist checkout --quiet "$DIST_REF"

nfpm package --config nfpm.yaml --packager deb --target out/
printf '%s-%s\n' "$CADDY_VERSION" "$PKG_RELEASE" > out/version.txt

# Windows: the same build for windows/amd64, as a zip with windows/Update-Caddy.ps1. Caddy's
# own release embeds Caddy's icon and a version resource through xcaddy
# (internal/utils/resource.go, which uses goversioninfo); this does the same, with the package
# version as file version (2.11.9-16 as 2.11.9.16), so that Update-Caddy.ps1 reads the
# installed version from caddy.exe itself. Its four parts are 16 bits each.
if ! [[ "$CADDY_VERSION" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)$ ]]
then
    echo "FAIL: Caddy version $CADDY_VERSION is not x.y.z, as the Windows file version needs it" >&2
    exit 1
fi
ver_major="${BASH_REMATCH[1]}" ver_minor="${BASH_REMATCH[2]}" ver_patch="${BASH_REMATCH[3]}"
for part in "$ver_major" "$ver_minor" "$ver_patch" "$PKG_RELEASE"
do
    if ! [[ "$part" =~ ^[0-9]+$ ]] || [ "$part" -gt 65535 ]
    then
        echo "FAIL: $CADDY_VERSION-$PKG_RELEASE does not fit a Windows file version (0-65535 each)" >&2
        exit 1
    fi
done

curl -fsSL -o build/windows/caddy.ico \
    "https://raw.githubusercontent.com/caddyserver/xcaddy/$XCADDY_REF/internal/utils/resources/ico/caddy.ico"
echo "$CADDY_ICO_SHA256  build/windows/caddy.ico" | sha256sum -c -

cat > build/windows/versioninfo.json <<EOF
{
  "FixedFileInfo": {
    "FileVersion": { "Major": $ver_major, "Minor": $ver_minor, "Patch": $ver_patch, "Build": $PKG_RELEASE },
    "ProductVersion": { "Major": $ver_major, "Minor": $ver_minor, "Patch": $ver_patch, "Build": $PKG_RELEASE },
    "FileFlagsMask": "3f",
    "FileFlags": "00",
    "FileOS": "040004",
    "FileType": "01",
    "FileSubType": "00"
  },
  "StringFileInfo": {
    "Comments": "Plugins: $PLUGINS. Built by github.com/MarcFauser/caddy-deb $PACKAGING_VERSION.",
    "CompanyName": "https://caddyserver.com/",
    "FileDescription": "Caddy web server with plugins",
    "FileVersion": "$CADDY_VERSION-$PKG_RELEASE",
    "InternalName": "caddy",
    "LegalCopyright": "The Caddy Authors",
    "OriginalFilename": "caddy.exe",
    "ProductName": "Caddy",
    "ProductVersion": "$CADDY_VERSION-$PKG_RELEASE"
  },
  "VarFileInfo": {
    "Translation": { "LangID": "0409", "CharsetID": "04B0" }
  }
}
EOF

# The .syso next to main.go is linked into the windows/amd64 build only (its file name is a
# build constraint); the trap above removes it.
go run "github.com/josephspurrier/goversioninfo/cmd/goversioninfo@$GOVERSIONINFO_VERSION" \
    -64=true -arm=false -icon build/windows/caddy.ico -o "$syso" build/windows/versioninfo.json
CGO_ENABLED=0 GOOS=windows GOARCH=amd64 go build \
    -trimpath -mod=readonly -ldflags '-s -w' -tags nobadger,nomysql,nopgx \
    -o build/windows/caddy.exe .
rm -f "$syso"
check_plugins_static build/windows/caddy.exe main.go

windows_zip="out/caddy_${CADDY_VERSION}-${PKG_RELEASE}_windows_amd64.zip"
cp LICENSE windows/Update-Caddy.cmd build/windows/
sed "s/@PACKAGING_VERSION@/$PACKAGING_VERSION/" windows/Update-Caddy.ps1 > build/windows/Update-Caddy.ps1
if grep -q '@PACKAGING_VERSION@' build/windows/Update-Caddy.ps1
then
    echo "FAIL: the packaging version was not filled into Update-Caddy.ps1" >&2
    exit 1
fi
(cd build/windows && zip -X -9 "../../$windows_zip" caddy.exe LICENSE Update-Caddy.ps1 Update-Caddy.cmd)
unzip -l "$windows_zip"

ls -l out/
dpkg-deb --info out/*.deb
dpkg-deb --contents out/*.deb
